import json
import tempfile
from pathlib import Path
from unittest.mock import patch
import settings

with tempfile.TemporaryDirectory(dir='.') as directory:
    root = Path(directory)
    target = root / 'settings.json'
    data = {'message': '안녕하세요 café 🌟', 'values': [1, True, None]}
    settings.save_settings(target, data)
    assert json.loads(target.read_text(encoding='utf-8')) == data
    assert '안녕하세요' in target.read_text(encoding='utf-8')
    assert set(root.iterdir()) == {target}
    settings.save_settings(str(target), {'updated': 'é'})
    assert json.loads(target.read_text(encoding='utf-8')) == {'updated': 'é'}
    old = target.read_bytes()
    for destination in (target, root / 'new.json'):
        try:
            settings.save_settings(destination, {'partial': [1, object()]})
        except TypeError:
            pass
        else:
            raise AssertionError('serialization error not propagated')
        assert target.read_bytes() == old
        assert set(root.iterdir()) == {target}
        failure = OSError('replacement failed')
        with patch.object(settings.os, 'replace', side_effect=failure):
            try:
                settings.save_settings(destination, data)
            except OSError as error:
                assert error is failure
            else:
                raise AssertionError('replacement error not propagated')
        assert target.read_bytes() == old
        assert set(root.iterdir()) == {target}
print('Passed: new/existing UTF-8 JSON, serialization/replacement failures, original preservation, temporary cleanup.')
